-- Durable cache invalidation operator queries. Bind variables are supplied by the owner application.
SELECT EVENT_ID, EVENT_KEY, TENANT_ID, NAMESPACE_NAME, CACHE_KEY_VALUE,
       EVENT_VERSION, REASON_TEXT, REQUESTED_BY, CREATED_AT
  FROM CPF_CACHE_INVALIDATION_EVENT
 WHERE EVENT_ID > :checkpoint
 ORDER BY EVENT_ID;
SELECT CONSUMER_ID, LAST_EVENT_ID, UPDATED_AT
  FROM CPF_CACHE_INVALIDATION_CHECKPOINT
 ORDER BY CONSUMER_ID;
